<?php
namespace App\Tests\Runtime;
use App\Runtime\RuntimePurchaseOrderAudit;
use PHPUnit\Framework\TestCase;
final class RuntimePurchaseOrderAuditTest extends TestCase
{
    public static function definition(): array { return ['entityCode'=>'procs_compra_med_progress','primaryKey'=>'proc_compra_id','apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros'],'apiSource'=>['responseContract'=>'sursum-programs']]; }
    public static function endpoint(string $op): array { return ['method'=>'POST','url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/ciw-cadastros','bodyTemplate'=>['resource'=>'procs_compra_med','operation'=>$op]]; }
    public static function row(): array { return ['proc_compra_id'=>17,'empresa_id'=>5,'qt_container'=>null,'cod_situacao'=>1,'cod_proc_fornec'=>'Legacy compra','qt_dias_translado'=>10,'cotacao_prevista'=>null,'observacao'=>'Observação','dt_registro'=>'2026-10-22','fornecedor_id'=>8,'dt_limite'=>null,'log_facilid_contato_fornec'=>true,'log_considerar_previsao'=>false,'nr_container_original'=>'12345678901234567890']; }
    public static function data(): array { return self::row()+['row_stamp'=>str_repeat('A',64)]; }
    public static function ledger(int $id=91,int $parent=17,int $type=3): array { return ['cta_corren_fornec_imp_id'=>$id,'fornecedor_id'=>8,'data'=>'2026-10-22','item_proc_compra_id'=>11,'historico'=>'Obrigações','cod_tipo_movto'=>$type,'vl_lancto'=>20.25,'cod_acao'=>3,'login'=>'real-user','data_hora'=>'2026-10-22T12:00:00.123','num_id_tit_ap'=>$type===4||$type===5?7:0,'item_container_id'=>$type===5||$type===10?71:0,'transacao_id'=>0,'proc_compra_id'=>$parent]; }
    public static function body(string $op='update'): array {
        $row=self::row();$before=$op==='create'?[]:$row;$after=$op==='delete'?[]:$row;
        return ['success'=>true,'committed'=>true,'data'=>$op==='delete'?[]:self::data(),'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'procs-compra','operation'=>$op,'recordId'=>17,'actor'=>['login'=>'real-user'],'before'=>$before,'after'=>$after,'changes'=>[],'warnings'=>[]]];
    }
    private function inspect(array $body,string $op='update',?array $d=null,?array $e=null,mixed $id=17,?string $actor='real-user'): array { return RuntimePurchaseOrderAudit::inspect($d??self::definition(),$e??self::endpoint($op),$body,$op,$id,$actor); }
    public function testImportsFullPhysicalImagesAndKeepsSyntheticStampsOutsideAudit(): void {
        foreach(['create','update','delete'] as $op){$body=self::body($op);$a=$this->inspect($body,$op);self::assertTrue($a['metadata']['available']);self::assertSame($body['audit']['before'],$a['before']);self::assertSame($body['audit']['after'],$a['after']);self::assertSame('procs_compra',$a['metadata']['resource']);self::assertSame(17,$a['metadata']['procCompraId']);self::assertSame(17,$a['metadata']['originProcCompraId']);self::assertArrayNotHasKey('row_stamp',$a['before']);self::assertArrayNotHasKey('row_stamp',$a['after']);}
    }
    public function testCollateralLedgerKeepsItsActualParentAndHistoricalDeletionActor(): void {
        $b=self::body();$old=self::ledger();foreach(['data','historico','vl_lancto','cod_acao','login','data_hora','num_id_tit_ap','item_container_id','transacao_id'] as $field)$old[$field]=null;$old['cod_tipo_movto']=99;
        $b['audit']['changes']=[['resource'=>'cta_corren_fornec_imp','operation'=>'delete','recordId'=>91,'before'=>$old,'after'=>[]],['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>92,'before'=>[],'after'=>self::ledger(92,18,5)]];
        $a=$this->inspect($b);self::assertTrue($a['metadata']['available']);self::assertCount(2,$a['events']);self::assertSame($old,$a['events'][0]['before']);self::assertSame(18,$a['events'][1]['metadata']['procCompraId']);self::assertSame(17,$a['events'][1]['metadata']['originProcCompraId']);self::assertSame(11,$a['events'][1]['metadata']['itemProcCompraId']);
    }
    public function testRejectsIncompleteForgedOrUncommittedEvidenceWithoutPartialImages(): void {
        foreach(['success','commit','source','resource','id','actor','actor-extra','missing-before','missing-field','unknown-field','stamp-in-main','date','decimal','bool','main-key','company','supplier','readonly-change','data-stamp','data-mismatch','warnings','change-resource','change-op','change-missing','change-key','change-login','change-type','change-action','change-transaction','change-parent','change-container','duplicate'] as $case){
            $b=self::body();$b['audit']['changes']=[['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>91,'before'=>[],'after'=>self::ledger()]];
            switch($case){case 'success':$b['success']=false;break;case 'commit':$b['committed']=false;break;case 'source':$b['audit']['source']='browser';break;case 'resource':$b['audit']['resource']='containers';break;case 'id':$b['audit']['recordId']='17';break;case 'actor':$b['audit']['actor']['login']='spoofed';break;case 'actor-extra':$b['audit']['actor']['id']=1;break;case 'missing-before':$b['audit']['before']=[];break;case 'missing-field':unset($b['audit']['after']['observacao']);break;case 'unknown-field':$b['audit']['after']['scope']=17;break;case 'stamp-in-main':$b['audit']['after']['row_stamp']=str_repeat('A',64);break;case 'date':$b['audit']['after']['dt_registro']='2026-02-30';break;case 'decimal':$b['audit']['after']['cotacao_prevista']='1,23';break;case 'bool':$b['audit']['after']['log_considerar_previsao']=1;break;case 'main-key':$b['audit']['after']['proc_compra_id']=18;break;case 'company':$b['audit']['after']['empresa_id']=0;break;case 'supplier':$b['audit']['after']['fornecedor_id']=0;break;case 'readonly-change':$b['audit']['after']['qt_container']=2;break;case 'data-stamp':$b['data']['row_stamp']=str_repeat('a',64);break;case 'data-mismatch':$b['data']['observacao']='different';break;case 'warnings':$b['audit']['warnings']=['key'=>'x'];break;case 'change-resource':$b['audit']['changes'][0]['resource']='containers';break;case 'change-op':$b['audit']['changes'][0]['operation']='update';$b['audit']['changes'][0]['before']=$b['audit']['changes'][0]['after'];break;case 'change-missing':unset($b['audit']['changes'][0]['after']['historico']);break;case 'change-key':$b['audit']['changes'][0]['after']['cta_corren_fornec_imp_id']=92;break;case 'change-login':$b['audit']['changes'][0]['after']['login']='historical-user';break;case 'change-type':$b['audit']['changes'][0]['after']['cod_tipo_movto']=6;break;case 'change-action':$b['audit']['changes'][0]['after']['cod_acao']=0;break;case 'change-transaction':$b['audit']['changes'][0]['after']['transacao_id']=1;break;case 'change-parent':$b['audit']['changes'][0]['after']['proc_compra_id']=0;break;case 'change-container':$b['audit']['changes'][0]['after']['item_container_id']=1;break;case 'duplicate':$b['audit']['changes'][]=$b['audit']['changes'][0];break;}
            $a=$this->inspect($b);self::assertFalse($a['metadata']['available'],$case);self::assertSame([],$a['before'],$case);self::assertSame([],$a['after'],$case);self::assertSame([],$a['events'],$case);
        }
        self::assertFalse($this->inspect(self::body(),actor:null)['metadata']['available']);self::assertFalse($this->inspect(self::body(),id:18)['metadata']['available']);
    }
    public function testBindingAndBusinessFieldLengthsAreClosed(): void {
        foreach([['entityCode'=>'other'],['primaryKey'=>'record_key'],['apiBinding'=>['sourceCode'=>'wrong']],['apiSource'=>['responseContract'=>'generic']]] as $delta)self::assertFalse($this->inspect(self::body(),d:array_replace_recursive(self::definition(),$delta))['metadata']['available']);
        foreach([['method'=>'GET'],['url'=>'https://evil.test/SursumPrograms/ciw-cadastros'],['bodyTemplate'=>['resource'=>'procs_compra_med','operation'=>'update','extra'=>1]]] as $delta)self::assertFalse($this->inspect(self::body(),e:array_replace(self::endpoint('update'),$delta))['metadata']['available']);
        foreach(['cod_proc_fornec'=>100,'observacao'=>16000,'nr_container_original'=>20] as $field=>$max){$b=self::body();$b['audit']['before'][$field]=$b['audit']['after'][$field]=$b['data'][$field]=str_repeat('Á',$max);self::assertTrue($this->inspect($b)['metadata']['available']);$b['audit']['after'][$field].='X';self::assertFalse($this->inspect($b)['metadata']['available']);}
    }
}
